    struct aic_mq_wrapper *w = kmm_zalloc(sizeof(struct aic_mq_wrapper));
    if (!w) {
        return -2;
    }

    w->storage = kmm_malloc((size_t)elt_size * (size_t)nb_elt);
    if (!w->storage) {
        kmm_free(w);
        return -2;
