static inline int rwnx_rx_scanu_start_cfm(struct rwnx_hw *rwnx_hw,
                                          struct rwnx_cmd *cmd,
                                          struct e2a_msg *msg)
{
    #if 1
    RWNX_DBG(RWNX_FN_ENTRY_STR);

    struct cfgrwnx_scan_completed resp;
    struct scanu_start_cfm *cfm = (struct scanu_start_cfm *)msg->param;
    memset(&resp, 0, sizeof(resp));
    aic_dbg("SCANU_START_CFM vif=%u status=%u result_cnt=%u mac_vif=%d\r\n",
            cfm->vif_idx, cfm->status, cfm->result_cnt, mac_vif_index);
    if(mac_vif_index != cfm->vif_idx) {
        aic_dbg("%s %d %d\r\n", __func__, mac_vif_index, cfm->vif_idx);
        return -1;
    }
    struct fhost_vif_tag *fhost_vif = fhost_from_mac_vif(cfm->vif_idx);

    resp.hdr.id = CFGRWNX_SCAN_DONE_EVENT;
    resp.hdr.len = sizeof(resp);
    resp.result_cnt = cfm->result_cnt;

    if (cfm->status == CO_OK)
        resp.status = CFGRWNX_SUCCESS;
    else
        resp.status = CFGRWNX_ERROR;

    if (fhost_vif == NULL || fhost_vif->scan_sock < 0) {
        aic_dbg("SCANU_START_CFM no WPA scan_sock, skip event status=%u result_cnt=%u\r\n",
                cfm->status, cfm->result_cnt);
        return 0;
    }

    int evt_ret = fhost_cntrl_cfgrwnx_event_send(&resp.hdr, fhost_vif->scan_sock);
    aic_dbg("SCANU_START_CFM send scan_sock=%d ret=%d status=%u result_cnt=%u\r\n",
            fhost_vif ? fhost_vif->scan_sock : -1, evt_ret,
            cfm->status, cfm->result_cnt);
    #endif
    return 0;
}

static inline int rwnx_rx_scanu_result_ind(struct rwnx_hw *rwnx_hw,
                                           struct rwnx_cmd *cmd,
                                           struct e2a_msg *msg)
{
    #if 1
    RWNX_DBG(RWNX_FN_ENTRY_STR);
    struct cfgrwnx_scan_result result;
    struct scanu_result_ind *ind = (struct scanu_result_ind *)msg->param;
    memset(&result, 0, sizeof(result));
    aic_dbg("SCANU_RESULT_IND vif=%u freq=%u rssi=%d len=%u mac_vif=%d\r\n",
            ind->inst_nbr, ind->center_freq, ind->rssi, ind->length,
            mac_vif_index);
    if(mac_vif_index != ind->inst_nbr) {
        aic_dbg("%s %d %d\r\n", __func__, mac_vif_index, ind->inst_nbr);
        return 0;
    }

    struct fhost_vif_tag *fhost_vif = fhost_from_mac_vif(ind->inst_nbr);

    fhost_scan_frame_handler(ind);
    if (fhost_vif == NULL || fhost_vif->scan_sock < 0) {
        aic_dbg("SCANU_RESULT_IND cached only scan_sock=%d freq=%u rssi=%d len=%u\r\n",
                fhost_vif ? fhost_vif->scan_sock : -1,
                ind->center_freq, ind->rssi, ind->length);
        return 0;
    }

    result.hdr.id = CFGRWNX_SCAN_RESULT_EVENT;
    result.hdr.len = sizeof(struct cfgrwnx_scan_result);

    result.fhost_vif_idx = CO_GET_INDEX(fhost_vif, fhost_env.vif);
    result.freq = ind->center_freq;
    result.rssi = ind->rssi;
    result.length = ind->length;
    result.payload = rtos_malloc(ind->length);
    if (result.payload == NULL)
        return 0;
    memcpy(result.payload, ind->payload, ind->length);

    int evt_ret = fhost_cntrl_cfgrwnx_event_send(&result.hdr, fhost_vif->scan_sock);
    aic_dbg("SCANU_RESULT_IND send scan_sock=%d ret=%d freq=%u rssi=%d len=%u payload=%p\r\n",
            fhost_vif ? fhost_vif->scan_sock : -1, evt_ret,
            ind->center_freq, ind->rssi, ind->length, result.payload);
    if (evt_ret) {
        rtos_free(result.payload);
    }
    #endif

