      ui_demo_wifi_notify(UI_DEMO_WIFI_EVENT_STOP_FINISHED);
      return ret;
    }

  ui_demo_wifi_notify(UI_DEMO_WIFI_EVENT_STATE_CHANGED);
  return 0;
}

